// ---------------------------------------------------------------------------
// slice 45 — ax13 `aW()` rope/vine swing (i.java:13182-13367)
// ---------------------------------------------------------------------------
class Slice45Test {

    /** ax13 record fixture — the shared L111 map:
     *  `[13,uid,x,y,aE,S,P,?, ?, ?, ?, aF,o,p,aG,ay]`. */
    private fun ax13At(w: Level0World, x: Int, y: Int, s: Int = 0,
                       ag: Int = 0, z1: Int = 10): Entity {
        val e = Entity(13, null)
        e.setPositionPx(x, y)
        val f = mutableListOf(13, 0, x, y, 0, s, 0)
        for (i in 7..13) f += 0
        f += ag            // r8[14] → aG
        f += 0             // r8[15] → ay
        w.npcFsm.initAx13(e, f)
        e.Z[1] = z1        // rope segment count
        w.npcs.add(e)
        return e
    }

    @Test fun `ax13 pendulum integrates only while displaced`() {
        val w = world(); w.npcs.clear()
        val e = ax13At(w, 100, 100)
        w.npcFsm.tickAx13(e, w, w.player)
        assertEquals(0, e.bP); assertEquals(0, e.bO)   // L5: bP==0 skips L6
        e.bO = 256                                      // displace → L6 runs
        val p0 = e.bP
        w.npcFsm.tickAx13(e, w, w.player)
        assertEquals(p0 + (256 shl 1), e.bP, "bP += bO<<1")
        assertTrue(e.bO < 256, "bO -= sin(n-θ)<<1 restoring force")
    }

    @Test fun `ax13 swing-side sign flip damps velocity by an eighth`() {
        val w = world(); w.npcs.clear()
        val e = ax13At(w, 100, 100)
        e.bO = -512; e.bP = 512                         // swinging left, +angle
        e.j = 1
        // integrate: bP += -1024 → negative → sign flip → damp
        w.npcFsm.tickAx13(e, w, w.player)
        assertEquals(-1, e.j, "side latch follows bP sign")
    }

    @Test fun `ax13 grab latch binds the player and arms the hang`() {
        val w = world(); w.npcs.clear()
        val p = w.player
        val e = ax13At(w, p.ak, p.al - 40, ag = 0, z1 = 10)
        e.bN = 6                                          // rope mid-swing
        p.setAnim(18)                                     // grabbable (g.b)
        p.N = p.ak shl 8; p.O = (e.O + 2000)             // inside arc box
        p.refreshBoxes()
        // drive the arc box against the player's W
        w.npcFsm.tickAx13(e, w, p)
        if (p.bM === e) {
            assertEquals(1, e.aA, "aA=1 attached")
            assertEquals(101, p.az, "aS.az=101")
            assertTrue(p.aA and 64 != 0, "aS.aA|=64")
            assertEquals(326, p.S, "i(326) hang anim")
        } else {
            // geometry-dependent arm — assert no crash at minimum
            assertTrue(e.aA == 0 || p.bM === e)
        }
    }

    @Test fun `ax13 aG4 spawner counts segments while the ax58 gate is open`() {
        val w = world(); w.npcs.clear()
        val e = ax13At(w, 100, 100, ag = 4, z1 = 10)
        e.Z[6] = -1                                       // no link → grow
        e.bN = 2
        w.npcFsm.tickAx13(e, w, w.player)
        assertEquals(3, e.bN, "Z[6]==-1 → bN++")
        e.bN = 10
        w.npcFsm.tickAx13(e, w, w.player)
        assertEquals(10, e.bN, "bN >= Z[1] caps the spawner")
        val door = Entity(58, null).apply { aw = 42; setAnim(2) }  // closed
        w.npcs.add(door)
        e.Z[6] = 42; e.bN = 2
        w.npcFsm.tickAx13(e, w, w.player)
        assertEquals(2, e.bN, "linked + !bf() → no growth")
        door.setAnim(1)                                    // bf() open set
        w.npcFsm.tickAx13(e, w, w.player)
        assertEquals(3, e.bN, "bf() gate open → bN++")
    }

    @Test fun `ax13 release flings the rider with the aG1 leap arc`() {
        val w = world(); w.npcs.clear()
        val p = w.player
        val e = ax13At(w, p.ak, p.al - 40, ag = 1)
        e.aA = 1; e.bM = p; p.bM = e; p.aA = p.aA or 64
        e.bO = 300; e.bP = -512                          // velocity flip window
        val o0 = e.bO
        // integrator flips bO sign → r0*bO<0 → aS.j()
        repeat(6) { if (p.bM === e) w.npcFsm.tickAx13(e, w, p) }
        assertNull(p.bM, "release unlinks")
        assertTrue(p.S == 23 || p.bM === e, "aG1 → i(23) leap")
    }

    @Test fun `g k rope input pumps and climbs`() {
        val w = world(); w.npcs.clear()
        val p = w.player
        val e = ax13At(w, 100, 100, ag = 1, z1 = 10)
        e.aA = 1; e.bM = p; p.bM = e
        e.bN = 5
        p.setAnim(326)
        // UP held with dead pendulum → climb one segment (L92)
        w.pad.held = 16388
        w.npcFsm.tickAx13(e, w, p)
        assertEquals(4, e.bN, "u(16388) → bN--")
        assertEquals(82, p.S, "i(82) climb anim")
        // descend at bottom of rope → L113 drop keeps bM (verbatim)
        e.bN = 9; p.setAnim(326); p.aA = p.aA or 64
        w.pad.held = 33024
        e.bO = 0; e.bP = 0
        w.npcFsm.tickAx13(e, w, p)
        assertEquals(43, p.S, "bN+2 > Z[1]-2 → i(43) drop")
        assertTrue(p.bM === e, "verbatim: L116 does not clear aS.bM")
    }
}


// =====================================================================
// Slice 43c — i.a() big-op decoder (script ops 100-114).
// =====================================================================

private fun op100(uid: Int, sub: Int, arg: Int) =
    byteArrayOf(100) + u16le(uid) + u16le(sub) + u16le(arg)
private fun op101(v: Int) = byteArrayOf(101) + u16le(v)
private fun op102(id: Int, flag: Int) = byteArrayOf(102) + u16le(id) + u16le(flag)
private fun op104(v: Int) = byteArrayOf(104) + u16le(v)
private fun op105(r9: Int, str: Int, r11: Int) =
    byteArrayOf(105, r9.toByte()) + u16le(str) + byteArrayOf(r11.toByte())
private fun op106(uid: Int, a: Int, b: Int, c: Int, d: Int) =
    byteArrayOf(106) + u16le(uid) + u16le(a) + u16le(b) + u16le(c) +
        byteArrayOf(d.toByte())
private fun op107(mask: Int) = byteArrayOf(107) + u16le(mask)
private fun op108(pass: Int, fail: Int) =
    byteArrayOf(108) + u16le(pass) + u16le(fail)
private fun op109(x0: Int, y0: Int, x1: Int, y1: Int) =
    byteArrayOf(109) + u16le(x0) + u16le(y0) + u16le(x1) + u16le(y1)
private fun op110(a: Int, b: Int) = byteArrayOf(110) + u16le(a) + u16le(b)
private fun op111(s: Int, x: Int, y: Int, f: Int, az: Int) =
    byteArrayOf(111) + u16le(s) + u16le(x) + u16le(y) +
        byteArrayOf(f.toByte()) + u16le(az)
private fun op112(a: Int, b: Int, c: Int) =
    byteArrayOf(112) + u16le(a) + u16le(b) + u16le(c)
private fun op113(pass: Int, fail: Int) =
    byteArrayOf(113) + u16le(pass) + u16le(fail)
private fun op114(str: Int, cd: Int) =
    byteArrayOf(114) + u16le(str) + u16le(cd)

class Slice43cTest {

    // -- prologue (i.java:20060): only 108/113 run bodies before key ---

    @Test fun `non-108 ops are consumed but only fire at step==key`() {
        val w = scriptedWorld(
            scriptBlock(0, 0, scriptGroup(10, op101(5))))
        val e = claimer(w)
        e.runClaimScript(w)                    // r02=0: consumed, not fired
        assertEquals(-1, e.cP, "op101 must not write cP before its key")
        repeat(9) { e.runClaimScript(w) }      // r02=1..9
        assertEquals(-1, e.cP)
        e.runClaimScript(w)                    // r02=10 = key: fires
        assertEquals(5, e.cP)
    }

    // -- op100 (L12): uid/sub dispatch + the r04 arg-switch -------------

    @Test fun `op100 sub1 arg-switch 0 arms P32+P128 and drops ae link`() {
        val w = scriptedWorld(
            scriptBlock(0, 0, scriptGroup(0, op100(900, 1, 0))))
        val e = claimer(w)
        val t = Entity(11, null).apply { aw = 900; P = 16 }
        t.ae = Entity(11, null)
        w.npcs.add(t)
        e.runClaimScript(w)
        assertTrue(t.P and 32 != 0 && t.P and 128 != 0, "r04=0 → P|=32|128")
        assertEquals(0, t.P and 16, "r04=0 → P&=~16")
        assertNull(t.ae, "r04=0 → G() drops ae")
    }

    @Test fun `op100 sub0 skips when arg is 0, runs arg-switch otherwise`() {
        val w = scriptedWorld(scriptBlock(0, 0,
            scriptGroup(0, op100(0, 0, 0)), scriptGroup(1, op100(0, 0, 5))))
        val e = claimer(w)
        val before = e.P
        e.runClaimScript(w)                    // sub0 arg0 → no-op
        assertEquals(before, e.P)
        e.runClaimScript(w)                    // sub0 arg5 → P^=1024
        assertTrue(e.P and 1024 != 0, "r04=5 → P^1024")
    }

    @Test fun `op100 sub2 removes the uid entity`() {
        val w = scriptedWorld(
            scriptBlock(0, 0, scriptGroup(0, op100(900, 2, 0))))
        val e = claimer(w)
        val t = Entity(11, null).apply { aw = 900 }
        w.npcs.add(t)
        e.runClaimScript(w)
        assertTrue(t in w.pendingRemove, "sub2 → k.c(r05)")
    }

    @Test fun `op100 sub4 az-flag and sub5 az-write`() {
        val w = scriptedWorld(scriptBlock(0, 0,
            scriptGroup(0, op100(900, 4, 77)), scriptGroup(1, op100(0, 5, 55))))
        val e = claimer(w)
        val t = Entity(11, null).apply { aw = 900 }
        w.npcs.add(t)
        e.runClaimScript(w)
        assertTrue(w.kAb, "sub4 → k.ab = true")
        assertEquals(77, t.az, "sub4 → r05.az = r04")
        e.runClaimScript(w)
        assertEquals(55, e.az, "sub5 uid0 → this.az = r04")
