    // -- op108 single-button QTE (L133) ---------------------------------

    @Test fun `op108 press sets cb1 and the key branches to pass`() {
        val w = scriptedWorld(scriptBlock(0, 0,
            scriptGroup(0, op107(32)),
            scriptGroup(10, op108(7, 0))))
