class Slice50Test {

    /** ax46 record (i.java:2700 → L206): `[46, aw, x, y, aE, S, P, az,
     *  z0(r8[8]), z1(r8[9]), clipIdx(r8[10]), pal(r8[11]), z7(r8[12])]`.
     *  `k.bl = {29, 0}` rebinds the anim clip by r8[10]. */
    private fun ax46At(w: Level0World, x: Int, y: Int, s: Int,
                       z0: Int = 0, z1: Int = 0, ci: Int = 0,
                       pal: Int = 0, z7: Int = 0): Entity {
        val e = Entity(46, w.clips[29])
        e.setPositionPx(x, y)
        val f = mutableListOf(46, 0, x, y, 0, s, 0, 0, z0, z1, ci, pal, z7)
        while (f.size < 16) f += 0
        w.npcFsm.initAx46(e, f, w)
        w.npcs.add(e)
        return e
    }

    @Test fun `init binds clip29 for bl-0 records and loads Z`() {
        val w = world(); w.npcs.clear()
        val e = ax46At(w, 200, 400, 0, z0 = 50, z1 = -40, pal = 2, z7 = 9)
        assertSame(w.clips[29], e.clip, "L15 aa = k.r(bl[0]) = clip29")
        assertEquals(0, e.S)
        assertEquals(50 shl 8, e.Z[0]); assertEquals(-40 shl 8, e.Z[1])
        assertEquals(30, e.Z[3]); assertEquals(0, e.Z[4])
        assertEquals(2, e.Z[5]); assertEquals(29, e.Z[6]); assertEquals(9, e.Z[7])
    }

    @Test fun `init binds clip0 for bl-1 armed records`() {
        val w = world(); w.npcs.clear()
        val e = ax46At(w, 2389, 386, 327, ci = 1, pal = 2)
        assertSame(w.clips[0], e.clip, "L15 aa = k.r(bl[1]) = clip0")
        assertEquals(327, e.S, "i(r8[5]) accepts 327 on the mega clip")
        assertEquals(327, e.Z[4], "armed marker Z[4]=r8[5]")
        assertEquals(0, e.Z[6])
    }

    @Test fun `head pins the palette to Z5 each tick`() {
        val w = world(); w.npcs.clear()
        val e = ax46At(w, 200, 400, 2, pal = 2)
        w.npcFsm.tickAx46(e, w, w.player)
        assertEquals(2, e.palette, "aa.l(Z[5])")
    }

    @Test fun `spring arm launches the falling player off the pad`() {
        val w = world(); w.npcs.clear()
        val e = ax46At(w, 200, 400, 0, z0 = 50, z1 = -40)
        // clip29 S0 rect = [-27,-12,53,8] → W = [173,388,226,396]
        assertEquals(173, e.W[0]); assertEquals(388, e.W[1])
        assertEquals(226, e.W[2]); assertEquals(396, e.W[3])
        val p = w.player
        p.setPositionPx(200, 390); p.refreshBoxes()
        p.S = 43; p.ah = 512                            // falling onto it
        w.npcFsm.tickAx46(e, w, p)
        assertEquals(388, p.al, "op11 → al = pad top")
        assertEquals(200, p.ak, "op11 → ak = pad anchor")
        assertEquals(-40 shl 8, p.ah, "op11 → ah = Z[1]")
        assertEquals(50 shl 8, p.ag, "op11 → ag = Z[0]")
        assertEquals(22, p.S, "Z[0]!=0 → i(22)")
        assertFalse(p.av, "Z[0]>0 → av=false")
        assertEquals(1, e.S, "L88 → i(1) sprung")
    }

    @Test fun `spring ignores a rising player`() {
        val w = world(); w.npcs.clear()
        val e = ax46At(w, 200, 400, 0, z0 = 50, z1 = -40)
        val p = w.player
        p.setPositionPx(200, 390); p.refreshBoxes()
        p.S = 43; p.ah = -512                            // still moving up
        w.npcFsm.tickAx46(e, w, p)
        assertEquals(43, p.S, "L82 ah<0 → no bounce")
        assertEquals(0, e.S)
    }

    @Test fun `S1 settle returns the pad to i0 on anim end`() {
        val w = world(); w.npcs.clear()
        val e = ax46At(w, 200, 400, 1)
        e.T = w.clips[29]!!.frameCount(1) - 1
        e.U = w.clips[29]!!.frameDuration(1, e.T) - 1
        w.npcFsm.tickAx46(e, w, w.player)
        assertEquals(0, e.S, "L71 → i(0)")
    }

    @Test fun `armed S327 pins the overlapping player via op24`() {
        val w = world(); w.npcs.clear()
        val e = ax46At(w, 200, 400, 327, ci = 1, pal = 2)
        assertTrue(e.X[2] > e.X[0], "clip0 S327 carries a real attack box")
        val p = w.player
        p.setPositionPx((e.X[0] + e.X[2]) / 2, (e.X[1] + e.X[3]) / 2)
        p.refreshBoxes(); p.S = 18
        w.npcFsm.tickAx46(e, w, p)
        assertEquals(330, p.S, "aS.a(24,330) pins anim 330")
        assertEquals(e.W[0], p.ak, "L49 → ak = src.W[0]")
        assertEquals(e.W[1], p.al, "L49 → al = src.W[1]")
        assertEquals(0, p.ag); assertEquals(0, p.ah); assertEquals(0, p.aj)
        assertEquals(328, e.S, "L13 → i(328)")
    }

    @Test fun `S328 release throws the player off and rearms`() {
        val w = world(); w.npcs.clear()
        val e = ax46At(w, 200, 400, 328, ci = 1, pal = 2)
        val p = w.player
        p.setPositionPx((e.X[0] + e.X[2]) / 2, (e.X[1] + e.X[3]) / 2)
        p.refreshBoxes(); p.S = 330
        e.av = true
        e.T = w.clips[0]!!.frameCount(328) - 1
        e.U = w.clips[0]!!.frameDuration(328, e.T) - 1
        w.npcFsm.tickAx46(e, w, p)
        assertEquals(329, e.S, "L46 → i(329)")
        assertEquals(165, p.S, "aS.i(165)")
        assertTrue(p.av, "aS.av = e.av")
        assertEquals(-2048, p.ag, "av → -2048")
        assertEquals(-5120, p.ah)
        assertEquals(30, e.Z[2], "L60 → Z[2]=Z[3]")
        // S329 → i(327) re-arm
        e.T = w.clips[0]!!.frameCount(329) - 1
        e.U = w.clips[0]!!.frameDuration(329, e.T) - 1
        w.npcFsm.tickAx46(e, w, p)
        assertEquals(327, e.S, "L67 → i(327)")
    }

    @Test fun `unarmed touch throws the player off the trap`() {
        val w = world(); w.npcs.clear()
        val e = ax46At(w, 200, 400, 3)                    // Z[4]=3==S armed!
        // Z[4]==S here → this one is armed; spawn unarmed via record S
        val e2 = ax46At(w, 300, 400, 3)
        e2.Z[4] = 99                                    // disarm manually
        val p = w.player
        p.setPositionPx((e2.X[0] + e2.X[2]) / 2, (e2.X[1] + e2.X[3]) / 2)
        p.refreshBoxes(); p.S = 18
        w.npcFsm.tickAx46(e2, w, p)
        assertEquals(165, p.S, "L11 → aS.i(165)")
        assertEquals(if (e2.av) -2048 else 2048, p.ag)
        assertEquals(-5120, p.ah)
        assertEquals(7, e2.S, "L11 → i(7)")
    }

    @Test fun `S7 settles to the dead i2 arm`() {
        val w = world(); w.npcs.clear()
        val e = ax46At(w, 200, 400, 7)
        e.T = w.clips[29]!!.frameCount(7) - 1
        e.U = w.clips[29]!!.frameDuration(7, e.T) - 1
        w.npcFsm.tickAx46(e, w, w.player)
        assertEquals(2, e.S, "L63 → i(2)")
    }

    @Test fun `S10 pusher jets the player with record velocity`() {
        val w = world(); w.npcs.clear()
        val e = ax46At(w, 200, 400, 10, z0 = 30, z1 = -60)
        val p = w.player
        p.setPositionPx(e.W[0] + 2, e.W[1] + 2); p.refreshBoxes()
        p.S = 18
        e.av = false
        w.npcFsm.tickAx46(e, w, p)
        assertEquals(30 shl 8, p.ag, "L94 → ag = Z[0]")
        assertEquals(-60 shl 8, p.ah, "L94 → ah = Z[1]")
        assertTrue(p.av, "L98 → aS.av = !e.av")
        assertEquals(242, p.S, "L99 → aS.i(242)")
    }
}

// =====================================================================
// Slice 51 — ax7 ejection slot (i.java L88/L90/L94 :5110-5149, proven).
// =====================================================================

class Slice51Test {

    /** ax7 record: `[7, aw, x, y, aE, S, P, az(r8[7]), r8[8]]` — the
     *  slot has no Z; init stores `az` then `i(r8[5])+t()`. */
    private fun ax7At(w: Level0World, x: Int, y: Int, s: Int,
                      az: Int = 0, r8: Int = 1): Entity {
        val e = Entity(7, w.clips[60])
        e.setPositionPx(x, y)
        val f = mutableListOf(7, 0, x, y, 0, s, 0, az, r8)
        while (f.size < 16) f += 0
        w.npcFsm.initAx7(e, f, w)
        w.npcs.add(e)
        return e
    }

    @Test fun `init stores az and binds clip60`() {
        val w = world(); w.npcs.clear()
        val e = ax7At(w, 1397, 506, 0, az = 1)
        assertSame(w.clips[60], e.clip, "bi[7]=60")
        assertEquals(0, e.S); assertEquals(1, e.az)
        assertTrue(e.W[2] > e.W[0], "clip60 S0 has a real box")
    }

    @Test fun `S0 swallows the overlapping player into the slot`() {
        val w = world(); w.npcs.clear()
        val e = ax7At(w, 1397, 506, 0)
        e.av = false
        val p = w.player
        p.setPositionPx((e.W[0] + e.W[2]) / 2, (e.W[1] + e.W[3]) / 2)
        p.refreshBoxes(); p.S = 18; p.ah = 400; p.ag = -300
        w.npcFsm.tickAx7(e, w, p)
        assertEquals(1, e.S, "L90 → i(1)")
        assertEquals(313, p.S, "aS.i(313)")
        assertTrue(p.P and 64 != 0, "aS.P |= 64")
        assertEquals((e.W[0] + e.W[2]) shr 1, p.ak, "center snap x")
        assertEquals((e.W[1] + e.W[3]) shr 1, p.al, "center snap y")
        assertFalse(p.av, "aS.av = e.av")
        assertEquals(0, p.ah); assertEquals(0, p.ag)
        assertEquals(0, p.aj); assertEquals(0, p.ai)
    }

    @Test fun `S0 skips a player holding a marker`() {
        val w = world(); w.npcs.clear()
        val e = ax7At(w, 1397, 506, 0)
        val p = w.player
        p.setPositionPx((e.W[0] + e.W[2]) / 2, (e.W[1] + e.W[3]) / 2)
        p.refreshBoxes(); p.S = 18
        // p.isHolding() == true: ci in front, |Δak|<120, |Δal|<20
        val c = Entity(14, null)
        c.setPositionPx(p.ak + 10, p.al)
        p.ci = c; p.av = false
        w.npcFsm.tickAx7(e, w, p)
        assertEquals(0, e.S, "L90 k.aS.f() gate → no swallow")
        assertEquals(18, p.S)
    }

    @Test fun `S1 holds the player center-synced then ejects`() {
        val w = world(); w.npcs.clear()
        val e = ax7At(w, 1397, 506, 1)
        e.av = true
        val p = w.player
        p.setPositionPx(500, 500); p.refreshBoxes(); p.S = 313
        // mid-anim: still held
        e.T = 0; e.U = 0
        w.npcFsm.tickAx7(e, w, p)
        assertEquals((e.W[0] + e.W[2]) shr 1, p.ak, "L94 re-snap each tick")
        assertEquals((e.W[1] + e.W[3]) shr 1, p.al)
        assertEquals(e.T, p.T, "aS.T = this.T frame-sync")
        assertTrue(p.P and 64 != 0)
        assertEquals(1, e.S, "r()==false → still swallowing")
        // anim end: eject
        e.T = w.clips[60]!!.frameCount(1) - 1
        e.U = w.clips[60]!!.frameDuration(1, e.T) - 1
        w.npcFsm.tickAx7(e, w, p)
        assertEquals(0, e.S, "L94 r() → i(0)")
        assertEquals(-2048, p.ag, "av → -2048 eject")
    }

    @Test fun `S1 ejects rightward when the slot faces left-off`() {
        val w = world(); w.npcs.clear()
        val e = ax7At(w, 1397, 506, 1)
        e.av = false
        e.T = w.clips[60]!!.frameCount(1) - 1
        e.U = w.clips[60]!!.frameDuration(1, e.T) - 1
        w.npcFsm.tickAx7(e, w, w.player)
        assertEquals(2048, w.player.ag, "av=false → +2048")
    }
}


// ===========================================================================
// Slice 52 — ax72/ax78 counterweight pair + ax79 palette prop
// (init L384/L153/L386; ax78 `bA()` i.java:17525)
// ===========================================================================
class Slice52Test {

    private fun ax72At(w: Level0World, x: Int, y: Int, s: Int,
                       az: Int = 0, partnerAw: Int = -1,
                       drop: Int = 0): Entity {
        val e = Entity(72, w.clips[51])
        e.setPositionPx(x, y)
        val f = mutableListOf(72, 0, x, y, 0, s, 0, az, 10, drop, 20, 30, partnerAw)
        while (f.size < 16) f += 0
        w.npcFsm.initAx72(e, f, w)
        w.npcs.add(e)
        return e
    }

    private fun ax78At(w: Level0World, x: Int, y: Int, s: Int,
                       az: Int = 0): Entity {
        val e = Entity(78, w.clips[63])
        e.setPositionPx(x, y)
        val f = mutableListOf(78, 0, x, y, 0, s, 0, az)
        while (f.size < 16) f += 0
        w.npcFsm.initAx78(e, f, w)
        w.npcs.add(e)
        return e
    }

    private fun ax79At(w: Level0World, x: Int, y: Int, s: Int,
                       palette: Int = 0): Entity {
        val e = Entity(79, w.clips[0])
        e.setPositionPx(x, y)
        val f = mutableListOf(79, 0, x, y, 0, s, 0, palette, 77)
        while (f.size < 16) f += 0
        w.npcFsm.initAx79(e, f, w)
        w.npcs.add(e)
        return e
    }

    /** first support cell (h(): v<12 ? v>=5 : true) in the fixture grid */
    private fun supportCell(w: Level0World): Pair<Int, Int> {
        for (cy in 1 until w.level.worldH / 20)
            for (cx in 1 until w.level.worldW / 20)
                if (w.collisionCell(cx, cy) >= 5) return cx to cy
        error("no support cell in fixture")
    }

    /** first non-support cell (v<5) with a support cell directly below it */
    private fun airAboveSupport(w: Level0World): Pair<Int, Int> {
        for (cy in 1 until w.level.worldH / 20 - 1)
            for (cx in 1 until w.level.worldW / 20)
                if (w.collisionCell(cx, cy) < 5 && w.collisionCell(cx, cy + 1) >= 5)
                    return cx to cy
        error("no air-above-support column in fixture")
    }

    @Test fun `ax72 init stores the partner link and fixed drop offset`() {
        val w = world(); w.npcs.clear()
        val e = ax72At(w, 2897, 445, 0, az = 3, partnerAw = 34, drop = 7)
        assertSame(w.clips[51], e.clip, "bi[72]=51")
        assertEquals(3, e.az, "L384 az=r8[7]")
        assertEquals(10, e.Z[0]); assertEquals(7 shl 8, e.Z[1], "Z[1]=r8[9]<<8")
        assertEquals(20, e.Z[2]); assertEquals(30, e.Z[3])
        assertEquals(34, e.Z[4], "Z[4]=r8[12] — linked ax78's aw")
        assertEquals(0, e.S)
    }

    @Test fun `ax78 init then S0 settles +2 until supported then arms`() {
        val w = world(); w.npcs.clear()
        val (cx, cy) = supportCell(w)
        // probe (al+10)/20 hits cy: place the weight 10px above the support row
        val e = ax78At(w, cx * 20, cy * 20 - 10, 0, az = 2)
        assertSame(w.clips[63], e.clip, "bi[78]=63")
        assertEquals(2, e.az)
        w.npcFsm.tickAx78(e, w, w.player)
        assertEquals(1, e.S, "L5/L8 supported → i(1)")
        // drop back to S0 on air: +2 settle each tick, stays S0
        val (ax, ay) = airAboveSupport(w)
        val e2 = ax78At(w, ax * 20, ay * 20 - 10, 0)
        val before = e2.al
        w.npcFsm.tickAx78(e2, w, w.player)
        assertEquals(0, e2.S, "unsupported → keep settling")
        assertEquals(before + 2, e2.al, "L8 al+=2")
    }

    @Test fun `ax78 S1 holds on support, drops to S2 when unsupported`() {
        val w = world(); w.npcs.clear()
        val (cx, cy) = supportCell(w)
        val e = ax78At(w, cx * 20, cy * 20 - 10, 1)
        w.npcFsm.tickAx78(e, w, w.player)
        assertEquals(1, e.S, "L11 supported → hold")
        val (ax, ay) = airAboveSupport(w)
        val e2 = ax78At(w, ax * 20, ay * 20 - 10, 1)
        w.npcFsm.tickAx78(e2, w, w.player)
        assertEquals(2, e2.S, "unsupported → i(2)")
        assertEquals(1536, e2.aj, "fall gravity aj=1536")
    }

    @Test fun `ax78 S2 whooshes at T4U0 then lands into S3 zeroed`() {
        val w = world(); w.npcs.clear()
        val (cx, cy) = supportCell(w)
        val e = ax78At(w, cx * 20, cy * 20 - 10, 2)
        e.T = 4; e.U = 0; e.ah = 2048; e.aj = 0
        w.sfxLog.clear()
        w.npcFsm.tickAx78(e, w, w.player)
        assertTrue(14 in w.sfxLog, "T==4&&U==0 → k.A(14) whoosh")
        assertEquals(3, e.S, "supported → i(3)")
        assertEquals(0, e.aj); assertEquals(0, e.ah, "landed velocity zeroed")
    }

    @Test fun `ax78 S2 keeps falling on air and S3 sweeps + re-drops`() {
        val w = world(); w.npcs.clear()
        val (ax, ay) = airAboveSupport(w)
        val e = ax78At(w, ax * 20, ay * 20 - 10, 2)
        e.T = 0; e.U = 0
        w.npcFsm.tickAx78(e, w, w.player)
        assertEquals(2, e.S, "still falling")
        assertEquals(1536, e.aj)
        // S3 on support: settle path keeps S3 and zeroes vel; on air aj=1536
        val (cx, cy) = supportCell(w)
        val e3 = ax78At(w, cx * 20, cy * 20 - 10, 3)
        e3.ah = 1024
        w.npcFsm.tickAx78(e3, w, w.player)
        assertEquals(3, e3.S); assertEquals(0, e3.ah); assertEquals(0, e3.aj)
        val e4 = ax78At(w, ax * 20, ay * 20 - 10, 3)
        w.npcFsm.tickAx78(e4, w, w.player)
        assertEquals(1536, e4.aj, "L28 air → gravity again")
    }

    @Test fun `ax79 init pins the palette slot`() {
        val w = world(); w.npcs.clear()
        val e = ax79At(w, 6456, 510, 79, palette = 2)
        assertSame(w.clips[0], e.clip, "bi[79]=0")
        assertEquals(2, e.palette, "L386 e.palette = Z[0] = r8[7]")
        assertEquals(2, e.Z[0]); assertEquals(77, e.Z[1])
        assertEquals(79, e.S, "S = r8[5] verbatim (record legitimately uses 79)")
    }

    @Test fun `level0 counterweight records link by aw`() {
        val w = world()
        val lever = w.npcs.find { it.ax == 72 && it.aw == 33 }
        val weight = w.findByAw(34)
        assertNotNull(lever); assertNotNull(weight)
        assertEquals(34, lever!!.Z[4], "ax72 uid33 → ax78 uid34")
        assertEquals(78, weight!!.ax)
    }
}
